44	                        && postcode.equals(existing.getPostcode())
45	                        && (matchId == null || existing.getId() < matchId)) {
46	                    matchId = existing.getId();
47	                }
48	            }
49	        }
50	        owner.setPossibleDuplicate(matchId != null);
51	        owner.setPossibleDuplicateOf(matchId);
