15	 * also be exactly the length that country uses: {@code '+61'} requires 9 national digits
16	 * and {@code '+1'} requires 10. A wrong length yields {@code null}. Country codes not
17	 * listed fall back to the generic 8-to-15 total-digit rule.
18	 *
19	 * <p>E.g. {@code "0412 345 678"} -> {@code "+61412345678"} and
20	 * {@code "+64 21 123 456"} -> {@code "+6421123456"}.
21	 */
22	public final class Telephones {
23	
24	    /** Recognised country code (without the {@code '+'}) -> required national-number length. */
25	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of(
26	            "61", 9,
27	            "1", 10);
